"""Temporary transport for the reviewed gameplay patch; excluded from delivery."""
from pathlib import Path
import base64, hashlib, json, os, re, subprocess, sys, zlib

PAYLOAD = ''''''
# Fix the transport alphabet at one copied token before validating the whole patch.
PAYLOAD = PAYLOAD.replace('MxaAyFya6Y3', 'MxaAyFva6Y3')
patch = zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(patch).hexdigest() == '694c041785f0fb5b10d9f09cee6d4a56a19cad25571fd503ee2a24bd5850dbd4'
evidence = Path('/tmp/fada-evidence'); evidence.mkdir(exist_ok=True)
(evidence / 'gameplay.patch').write_bytes(patch)
subprocess.run(['git','fetch','--depth=1','origin','main'],check=True)
base = subprocess.check_output(['git','rev-parse','FETCH_HEAD'],text=True).strip()
work = Path('/tmp/fada-delivery')
subprocess.run(['git','worktree','add','--detach',str(work),base],check=True)
os.chdir(work)
focused = [sys.executable,'-B','-m','unittest','tools.tests.test_adiscord_stp_party_survival','tools.tests.test_adiscord_val_stelander_defeat','tools.tests.test_adiscord_stp_gameplay_loop_regressions']
def runlog(name,command):
    with (evidence/name).open('w') as f:
        result=subprocess.run(command,stdout=f,stderr=subprocess.STDOUT)
    return result.returncode
runlog('baseline-focused.log',focused)
runlog('baseline-validation.log',[sys.executable,'-B','tools/validate_tc.py','--limit','300'])
with (evidence/'apply.log').open('w') as f:
    result=subprocess.run(['git','apply','--3way','--whitespace=error',str(evidence/'gameplay.patch')],stdout=f,stderr=subprocess.STDOUT)
if result.returncode:
    print((evidence/'apply.log').read_text())
    raise SystemExit(result.returncode)
rc=runlog('focused.log',focused)
print((evidence/'focused.log').read_text())
assert rc == 0, 'Focused regressions must pass before publishing'
runlog('validation.log',[sys.executable,'-B','tools/validate_tc.py','--limit','300'])
def issues(name):
    return {re.sub(r':\d+(?=:|\n| |$)',':LINE',line) for line in (evidence/name).read_text().splitlines() if line.startswith('- ')}
new=sorted(issues('validation.log')-issues('baseline-validation.log'))
(evidence/'new-validation-issues.json').write_text(json.dumps(new,indent=2))
assert not new, new
subprocess.run(['git','diff','--cached','--check'],check=True)
files=subprocess.check_output(['git','diff','--cached','--name-only'],text=True).splitlines()
assert len(files)==15, files
assert all(not p.startswith('.github/') and p!='tools/fada_council_patch.py' for p in files)
for name in files:
    content=Path(name).read_bytes()
    if name.startswith('localisation/'):
        assert content.startswith(b'\xef\xbb\xbf'), name
    elif name.endswith('.txt'):
        assert not content.startswith(b'\xef\xbb\xbf'), name
subprocess.run(['git','config','user.name','A-Discord development'],check=True)
subprocess.run(['git','config','user.email','81386071+worker2of2month@users.noreply.github.com'],check=True)
subprocess.run(['git','commit','-m','feat(stelander): make Fada decisive and add council revanche with final annexation'],check=True)
head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
branch='codex/fada-council-ready-'+os.environ['GITHUB_RUN_ID']
subprocess.run(['git','push','origin',head+':refs/heads/'+branch],check=True)
manifest={'base':base,'head':head,'branch':branch,'files':files,'new_validation_issues':new,'runtime_tested':False}
(evidence/'manifest.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps(manifest,indent=2))
